import os
from typing import Any, Dict, List, Optional

import boto3


class TextractLayoutExtractor:
    def __init__(
        self,
        region_name: Optional[str] = None,
        aws_access_key_id: Optional[str] = None,
        aws_secret_access_key: Optional[str] = None,
        aws_session_token: Optional[str] = None,
    ) -> None:
        self.client = boto3.client(
            "textract",
            region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1",
            aws_access_key_id=aws_access_key_id or os.getenv("AWS_ACCESS_KEY_ID"),
            aws_secret_access_key=aws_secret_access_key or os.getenv("AWS_SECRET_ACCESS_KEY"),
            aws_session_token=aws_session_token or os.getenv("AWS_SESSION_TOKEN"),
        )

    def extract(
        self,
        *,
        file_path: Optional[str] = None,
        s3_bucket: Optional[str] = None,
        s3_key: Optional[str] = None,
        include_tables: bool = True,
        include_forms: bool = True,
        include_layout: bool = True,
    ) -> Dict[str, Any]:
        if not file_path and not (s3_bucket and s3_key):
            raise ValueError("Provide either file_path or both s3_bucket and s3_key.")

        feature_types: List[str] = []
        if include_tables:
            feature_types.append("TABLES")
        if include_forms:
            feature_types.append("FORMS")
        if include_layout:
            feature_types.append("LAYOUT")

        if file_path:
            with open(file_path, "rb") as f:
                document = {"Bytes": f.read()}
        else:
            document = {"S3Object": {"Bucket": s3_bucket, "Name": s3_key}}

        response = self.client.analyze_document(
            Document=document,
            FeatureTypes=feature_types or ["LAYOUT"],
        )

        blocks = response.get("Blocks", [])
        block_map = {b["Id"]: b for b in blocks if "Id" in b}

        return {
            "raw_response": response,
            "pages": self._extract_pages(blocks),
            "lines": self._extract_lines(blocks),
            "words": self._extract_words(blocks),
            "tables": self._extract_tables(blocks, block_map),
            "forms": self._extract_forms(blocks, block_map),
            "layout": self._extract_layout(blocks),
        }

    def _extract_pages(self, blocks: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        pages = []
        for b in blocks:
            if b.get("BlockType") == "PAGE":
                pages.append(
                    {
                        "id": b.get("Id"),
                        "page": b.get("Page", 1),
                        "geometry": b.get("Geometry"),
                    }
                )
        return pages

    def _extract_lines(self, blocks: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        lines = []
        for b in blocks:
            if b.get("BlockType") == "LINE":
                lines.append(
                    {
                        "id": b.get("Id"),
                        "page": b.get("Page"),
                        "text": b.get("Text", ""),
                        "confidence": b.get("Confidence"),
                        "geometry": b.get("Geometry"),
                    }
                )
        return lines

    def _extract_words(self, blocks: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        words = []
        for b in blocks:
            if b.get("BlockType") == "WORD":
                words.append(
                    {
                        "id": b.get("Id"),
                        "page": b.get("Page"),
                        "text": b.get("Text", ""),
                        "confidence": b.get("Confidence"),
                        "geometry": b.get("Geometry"),
                    }
                )
        return words

    def _extract_tables(self, blocks: List[Dict[str, Any]], block_map: Dict[str, Dict[str, Any]]) -> List[Dict[str, Any]]:
        tables = []
        for b in blocks:
            if b.get("BlockType") != "TABLE":
                continue

            cells = []
            for rel in b.get("Relationships", []):
                if rel.get("Type") != "CHILD":
                    continue
                for child_id in rel.get("Ids", []):
                    child = block_map.get(child_id)
                    if not child or child.get("BlockType") != "CELL":
                        continue
                    cell_text = self._collect_text_from_block(child, block_map)
                    cells.append(
                        {
                            "id": child.get("Id"),
                            "row_index": child.get("RowIndex"),
                            "column_index": child.get("ColumnIndex"),
                            "row_span": child.get("RowSpan", 1),
                            "column_span": child.get("ColumnSpan", 1),
                            "text": cell_text,
                            "confidence": child.get("Confidence"),
                            "geometry": child.get("Geometry"),
                        }
                    )

            tables.append(
                {
                    "id": b.get("Id"),
                    "page": b.get("Page"),
                    "confidence": b.get("Confidence"),
                    "geometry": b.get("Geometry"),
                    "cells": sorted(cells, key=lambda c: (c["row_index"] or 0, c["column_index"] or 0)),
                }
            )
        return tables

    def _extract_forms(self, blocks: List[Dict[str, Any]], block_map: Dict[str, Dict[str, Any]]) -> List[Dict[str, Any]]:
        forms = []
        for b in blocks:
            if b.get("BlockType") != "KEY_VALUE_SET":
                continue

            entity_types = set(b.get("EntityTypes", []))
            if "KEY" not in entity_types:
                continue

            key_text = self._collect_text_from_block(b, block_map)
            value_texts = []
            for rel in b.get("Relationships", []):
                if rel.get("Type") != "VALUE":
                    continue
                for value_id in rel.get("Ids", []):
                    value_block = block_map.get(value_id)
                    if value_block:
                        value_texts.append(self._collect_text_from_block(value_block, block_map))

            forms.append(
                {
                    "id": b.get("Id"),
                    "page": b.get("Page"),
                    "key": key_text,
                    "value": " ".join(v for v in value_texts if v).strip(),
                    "confidence": b.get("Confidence"),
                    "geometry": b.get("Geometry"),
                }
            )
        return forms

    def _extract_layout(self, blocks: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        layout_types = {
            "LAYOUT_TITLE",
            "LAYOUT_HEADER",
            "LAYOUT_FOOTER",
            "LAYOUT_SECTION_HEADER",
            "LAYOUT_PAGE_NUMBER",
            "LAYOUT_LIST",
            "LAYOUT_FIGURE",
            "LAYOUT_TABLE",
            "LAYOUT_KEY_VALUE",
            "LAYOUT_TEXT",
        }

        layout = []
        for b in blocks:
            block_type = b.get("BlockType")
            if block_type in layout_types:
                layout.append(
                    {
                        "id": b.get("Id"),
                        "type": block_type,
                        "page": b.get("Page"),
                        "text": b.get("Text", ""),
                        "confidence": b.get("Confidence"),
                        "geometry": b.get("Geometry"),
                    }
                )
        return layout

    def _collect_text_from_block(self, block: Dict[str, Any], block_map: Dict[str, Dict[str, Any]]) -> str:
        tokens: List[str] = []
        for rel in block.get("Relationships", []):
            if rel.get("Type") != "CHILD":
                continue
            for child_id in rel.get("Ids", []):
                child = block_map.get(child_id)
                if not child:
                    continue
                if child.get("BlockType") == "WORD":
                    tokens.append(child.get("Text", ""))
                elif child.get("BlockType") == "SELECTION_ELEMENT":
                    if child.get("SelectionStatus") == "SELECTED":
                        tokens.append("[X]")
                    else:
                        tokens.append("[ ]")
        return " ".join(t for t in tokens if t).strip()
